  "allow_hold_in_ims_call": {"note":"Flag indicating whether the carrier supports the Hold command while in an IMS call.\n\nThe device configuration value config_device_respects_hold_carrier_config ultimately controls whether this carrier configuration option is used. Where config_device_respects_hold_carrier_config is false, the value of this carrier configuration is ignored.","constant":"KEY_ALLOW_HOLD_IN_IMS_CALL_BOOL","type":"bool","hidden":true,"default":"true"},
