  "capabilities_exempt_from_single_dc_check_int_array": {"note":"Only apply if KEY_ONLY_SINGLE_DC_ALLOWED_INT_ARRAY specifies the network types that support a single data connection at a time. This key defines a list of network capabilities which, if requested, will exempt the request from single data connection checks.","constant":"KEY_CAPABILITIES_EXEMPT_FROM_SINGLE_DC_CHECK_INT_ARRAY","type":"int_array","since":34},
